import{_ as a,o,c as s,a2 as c}from"./chunks/framework.BS0bAV7E.js";const h=JSON.parse('{"title":"构建 Open Cube OS","description":"","frontmatter":{},"headers":[],"relativePath":"zh/root/BUILDING.md","filePath":"zh/root/BUILDING.md"}'),d={name:"zh/root/BUILDING.md"};function t(n,e,i,l,p,r){return o(),s("div",null,[...e[0]||(e[0]=[c(`<h1 id="构建-open-cube-os" tabindex="-1">构建 Open Cube OS <a class="header-anchor" href="#构建-open-cube-os" aria-label="Permalink to &quot;构建 Open Cube OS&quot;">​</a></h1><p>以下所有内容都是可执行的实体：文件名、目标及检查项均来自 <code>Makefile</code>、<code>tools/build.sh</code>、<code>tools/build.ps1</code> 和 CI 管道（<code>.github/workflows/build.yml</code>）。</p><h2 id="构建产物" tabindex="-1">构建产物 <a class="header-anchor" href="#构建产物" aria-label="Permalink to &quot;构建产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>产物</th></tr></thead><tbody><tr><td><code>make kernel</code></td><td><code>build/opencube.elf</code> - 内核 ELF（0 警告，<code>-Wall -Wextra -Werror</code>）</td></tr><tr><td><code>make iso</code></td><td><code>build/opencube.iso</code> - 混合 BIOS+UEFI 可启动 ISO</td></tr><tr><td><code>make src-zip</code></td><td><code>dist/OpenCubeOS-&lt;version&gt;-src.zip</code> - 确定性源码压缩包</td></tr><tr><td><code>make ota</code></td><td><code>dist/OpenCubeOS-&lt;version&gt;-update.tar.gz</code> - OTA 更新包</td></tr><tr><td><code>make all</code></td><td>内核 + ISO + 源码压缩包 + OTA</td></tr><tr><td><code>make test</code></td><td>宿主侧单元测试（<code>tools/run_host_tests.py</code>）</td></tr><tr><td><code>make reproducible-check</code></td><td>两次干净构建，字节完全一致的 ELF</td></tr><tr><td><code>make api-docs</code></td><td>真实树文档数据（<code>docs/data/*.json</code>）</td></tr></tbody></table><p>一键式入口：<code>tools/build.sh</code>（Linux；相同的目标名称，附带依赖检测和 <code>--install</code>）、<code>build.ps1</code>（通过 WSL2 / MSYS2 在 Windows 上运行）。</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><h3 id="依赖项" tabindex="-1">依赖项 <a class="header-anchor" href="#依赖项" aria-label="Permalink to &quot;依赖项&quot;">​</a></h3><p><code>gcc, ld (binutils), nasm, grub-mkimage (grub-common), xorriso, mtools (mformat/mcopy), python3, zip</code>。</p><p><code>tools/build.sh</code> 会检查所有依赖项，并打印任何缺失依赖的确切 Debian 包名；当你是 root 用户时，<code>./build.sh --install</code> 会通过 apt 安装它们。构建 ISO 额外需要 GRUB 模块树（<code>i386-pc</code> 需要 <code>grub-pc-bin</code>，<code>x86_64-efi</code> 需要 <code>grub-efi-amd64-bin</code>）和来自 <code>grub-common</code> 的 <code>unicode.pf2</code>。</p><p>用于 QEMU 测试：<code>qemu-system-x86</code>, <code>seabios</code>, <code>ipxe-qemu</code>, <code>ovmf</code> (UEFI)。在 Debian/Ubuntu 主机上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get install gcc nasm xorriso mtools \\</span></span>
<span class="line"><span>     grub-common grub-pc-bin grub-efi-amd64-bin zip python3 \\</span></span>
<span class="line"><span>     qemu-system-x86 ovmf</span></span></code></pre></div><h3 id="构建" tabindex="-1">构建 <a class="header-anchor" href="#构建" aria-label="Permalink to &quot;构建&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/cubestudio-dev/OpenCubeOS.git</span></span>
<span class="line"><span>cd OpenCubeOS</span></span>
<span class="line"><span>./build.sh            # = make all</span></span>
<span class="line"><span># or step by step:</span></span>
<span class="line"><span>make -j&quot;$(nproc)&quot; kernel</span></span>
<span class="line"><span>make iso</span></span></code></pre></div><p>版本横幅来自 Makefile 中的 <code>2.0.0</code> 字面量（可通过 <code>make OC_RELEASE_VERSION=1.0.1-test1</code> 覆盖）。构建号是提交计数加 +21 对齐偏移（见 Makefile 注释），使公开序列保持在已发布的 274 之上。</p><h3 id="启动与测试" tabindex="-1">启动与测试 <a class="header-anchor" href="#启动与测试" aria-label="Permalink to &quot;启动与测试&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios     # QEMU legacy BIOS boot</span></span>
<span class="line"><span>make run-uefi     # QEMU UEFI boot (OVMF)</span></span>
<span class="line"><span>make test         # host unit tests</span></span>
<span class="line"><span>make shot-bios    # boot screenshot capture</span></span></code></pre></div><p>启用网络：添加 <code>-netdev user,id=n1 -device e1000,netdev=n1</code>（<code>run-bios</code> 目标已添加），然后在客户机内执行 <code>dhcp</code>。</p><h3 id="确定性验证" tabindex="-1">确定性验证 <a class="header-anchor" href="#确定性验证" aria-label="Permalink to &quot;确定性验证&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make reproducible-check</span></span>
<span class="line"><span># reproducible-check: PASS - ELF byte-identical across two clean builds</span></span></code></pre></div><p>确定性源码（全部在树内验证）：无 <code>__DATE__</code>/<code>__TIME__</code>/<code>__TIMESTAMP__</code> 宏，相同输入下稳定的 <code>grub-mkimage</code> 输出，固定的链接顺序，<code>strip --strip-debug</code> 移除带路径的段。源码压缩包通过构造保证确定性（<code>git archive</code>：树顺序、提交 mtimes、索引权限）。OTA 包包含 UTC 构建日期 - 在同一天内可字节完全复现，这是文档保证的。</p><p>当导出并传递给打包子工具时，<code>SOURCE_DATE_EPOCH</code> 会被遵守。</p><h3 id="交叉编译-arm64-risc-v-点亮-shell" tabindex="-1">交叉编译（ARM64 / RISC-V 点亮 Shell） <a class="header-anchor" href="#交叉编译-arm64-risc-v-点亮-shell" aria-label="Permalink to &quot;交叉编译（ARM64 / RISC-V 点亮 Shell）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make ARCH=arm64    # build/arch/arm64/opencube-arm64.elf (PL011 UART shell)</span></span>
<span class="line"><span>make ARCH=riscv    # build/arch/riscv/opencube-riscv.elf (NS16550A UART shell)</span></span></code></pre></div><p>这些是真实的裸机点亮 Shell：带有真实除数编程的 PL011 / NS16550A UART、ARM 通用定时器 / RISC-V CLINT mtime 计数器，以及 1 秒心跳 - 在 QEMU 中实时验证横幅和递增的心跳（<code>qemu-system-aarch64 -M virt</code>、<code>qemu-system-riscv64 -M virt</code>）。完整的内核功能集仅限 x86_64。</p><p>交叉工具链包（Debian）： <code>gcc-aarch64-linux-gnu binutils-aarch64-linux-gnu</code>, <code>gcc-riscv64-linux-gnu binutils-riscv64-linux-gnu</code>, <code>qemu-system-arm</code>, <code>qemu-system-misc</code>。</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p><code>build.ps1</code>（PowerShell）将构建转发给来自最佳可用环境的同一个 Makefile，顺序如下：</p><ol><li><strong>WSL2</strong>（推荐）- 一个包含上述 Linux 依赖项的 Debian/Ubuntu WSL 发行版。脚本使用 <code>wslpath</code> 转换 Windows 路径并在 WSL 内部运行 <code>make</code>。</li><li><strong>MSYS2</strong> - 本地安装的 MSYS2，其 PATH 上有 <code>mingw-w64</code> gcc、nasm、mtools、xorriso、grub 包。</li><li>否则脚本会打印确切的安装包并退出非零状态码。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>powershell -ExecutionPolicy Bypass -File build.ps1            # full pipeline</span></span>
<span class="line"><span>powershell -ExecutionPolicy Bypass -File build.ps1 iso        # kernel + ISO</span></span></code></pre></div><h2 id="多配置构建" tabindex="-1">多配置构建 <a class="header-anchor" href="#多配置构建" aria-label="Permalink to &quot;多配置构建&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make defconfig          # write .config (all options on)</span></span>
<span class="line"><span>make menuconfig         # interactive configurator (tools/oc_menuconfig.sh)</span></span>
<span class="line"><span>make CONFIG_TUI=n       # one-shot override</span></span></code></pre></div><p>选项：<code>CONFIG_TUI</code>, <code>CONFIG_CHINESE</code>, <code>CONFIG_NVME</code>, <code>CONFIG_AHCI</code>, <code>CONFIG_VIRTIO_BLK</code>。<code>CONFIG_CHINESE=n</code> 会强制 <code>CONFIG_TUI=n</code>。 <code>CONFIG_TUI=n CONFIG_CHINESE=n</code> 的构建启动时有 216 条命令（233 - 17 条 TUI/中文命令）；完整配置启动时有 233 条。禁用路径是真实代码，而非被删除的代码 - 配置器生成的头文件将禁用的功能映射为空操作等价物。</p><h2 id="构建缓存" tabindex="-1">构建缓存 <a class="header-anchor" href="#构建缓存" aria-label="Permalink to &quot;构建缓存&quot;">​</a></h2><p>编译缓存（<code>tools/oc_cc.sh</code>）是内容寻址的：键是编译器身份 + 完整标志 + 源码及所有头文件依赖的内容哈希。在发布树上测量：冷启动 46.6 秒 -&gt; 热启动 14.4 秒（186/186 个对象命中，3.2 倍加速），热启动输出字节与冷启动完全一致。缓存控制：<code>make cache-stats</code>, <code>make cache-clear</code>。</p><h2 id="可脚本化的构建-api" tabindex="-1">可脚本化的构建 API <a class="header-anchor" href="#可脚本化的构建-api" aria-label="Permalink to &quot;可脚本化的构建 API&quot;">​</a></h2><p><code>tools/build.sh</code> 将其管道暴露为可源化的函数（<code>build_all</code>, <code>build_iso</code>, <code>config_load</code>, <code>cache_lookup</code>, <code>cross_compile</code>, ...），并通过 <code>tools/build.sh api-selftest</code> 验证规定的 8 个接口。发布脚本和 CI 组合这些函数而非解析 make 输出。</p><h2 id="ci" tabindex="-1">CI <a class="header-anchor" href="#ci" aria-label="Permalink to &quot;CI&quot;">​</a></h2><p><code>.github/workflows/build.yml</code> 在每次推送到 <code>main</code> 和 PR 时运行：检出（完整历史 + 标签以便 <code>git describe</code> 提供版本横幅）、依赖安装、内核（<code>-Wall -Wextra -Werror</code>）、混合 ISO、确定性源码压缩包、OTA 包、宿主测试套件、摘要 + 上传，以及可复现性门禁。QEMU 启动和 E2E 套件是发布主机活动（它们需要持久化的 /etc 卷固件）- 完整发布门禁见 <code>docs/release/</code>。</p><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><ul><li><strong><code>grub-mkimage: cannot open ... unicode.pf2</code></strong> - 字体位于 <code>grub-common</code>；如果发行版将其分割，请将 <code>OC_TOOLS</code> 指向包含 <code>usr/share/grub/unicode.pf2</code> 的目录树。</li><li><strong><code>src-zip: not a git checkout</code></strong> - 确定性源码压缩包需要 git 元数据；从克隆构建，或使用 <code>make dist</code> 作为基于 tar 的后备方案。</li><li><strong>QEMU 找不到固件</strong> - <code>OC_TOOLS</code> 会移动整个工具链；QEMU 的数据目录会在 <code>$OC_TOOLS/usr/share/qemu</code> 和 <code>$OC_TOOLS/share/qemu</code> 下探测。</li><li><strong>在非常新的 GCC/binutils 上出现 <code>setc</code> / <code>packed-member</code> 构建错误</strong> - 已在树内修复；更新至 CI 通过的提交 <code>fc4e5a5</code> 之后。</li></ul>`,40)])])}const b=a(d,[["render",t]]);export{h as __pageData,b as default};
